    key,
    "phase",
    "learning",
    "epoch",
    epoch,
    "cooldownUntil",
    0,
    "learningStartedAt",
    now,
    "observedTokens",
    tokens,
    "learnedLimit",
    0,
    "learnedWindowMillis",
